import { z } from "zod";
import { MarketResearchResult, MemoDraftResult, TeaserScreenResult } from "@contracts/schemas";
import type { Usage } from "./llm";

/** Job results as the API's OpenAPI document defines them (generated by `make codegen`). */
export const RESULT_SCHEMAS = {
  teaser_screen: TeaserScreenResult,
  market_research: MarketResearchResult,
  memo_draft: MemoDraftResult,
} as const;

export type ResultKind = keyof typeof RESULT_SCHEMAS;

/** Checks a final payload against the API contract; throws a message naming the contract so the job fails clearly. */
export function checkResult<K extends ResultKind>(kind: K, payload: unknown): z.infer<(typeof RESULT_SCHEMAS)[K]> {
  const parsed = RESULT_SCHEMAS[kind].safeParse(payload);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    throw new Error(`Result does not match the API contract: ${issue ? `${issue.path.join(".")} ${issue.message}` : "invalid"}.`);
  }
  return parsed.data as z.infer<(typeof RESULT_SCHEMAS)[K]>;
}
